DOCS = {k:pdfplumber.open(SOURCE / (v+'.pdf')) for k,v in NAMES.items()}
def dec(x): return Decimal(str(x).replace(',','').replace('，',''))
def compact(x): return ''.join(unicodedata.normalize('NFKC', x).split())
def evidence(label, page, snippet):
    p = DOCS[label].pages[page-1]
    chars = [c for line in p.extract_text_lines() for c in line['chars']]
    pairs = [(t,c) for c in chars for t in unicodedata.normalize('NFKC',c['text']) if not t.isspace()]
    text = ''.join(t for t,c in pairs)
    query = compact(snippet)
    pos = text.find(query)
    bbox = None
    if pos >= 0:
        found = [c for t,c in pairs[pos:pos+len(query)]]
        bbox = [round(min(c['x0'] for c in found),3),round(min(c['top'] for c in found),3),round(max(c['x1'] for c in found),3),round(max(c['bottom'] for c in found),3)]
    else:
        print('BBOX_NOT_LOCATED',label,page,snippet)
    return {'source':str(SOURCE/(NAMES[label]+'.pdf')),'page':page,'bbox':bbox,
            'bbox_coordinates':'PDF points, origin at top-left, [x0, top, x1, bottom]',
            'page_width':float(p.width),'page_height':float(p.height),'snippet':snippet,
            'location_status':'exact normalized character match' if bbox else '当前无法定位：原文片段未连续匹配'}

def rate(label, name, num, den, reported, page, snippet, kind='完成率', denominator_note=None):
    n,d,r = dec(num),dec(den),dec(reported)
    v = n/d*100 if d else None
    diff = abs(r-v) if v is not None else None
    return {'name':name,'kind':kind,'numerator_wanyuan':str(n),'denominator_wanyuan':str(d),
            'denominator_note':denominator_note or ('本项预算数' if kind=='完成率' else '对应合计决算数'),
            'formula':f'{n} / {d} * 100','decimal_result':str(v) if v is not None else None,
            'rounded_2dp':str(v.quantize(Decimal('.01'),rounding=ROUND_HALF_UP)) if v is not None else None,
            'reported_percent':str(r),'absolute_difference_pp':str(diff) if diff is not None else None,
            'tolerance_pp':'0.1','status':'confirmed_error' if diff is not None and diff>Decimal('.1') else 'within_tolerance',
            'evidence':evidence(label,page,snippet)}

def sumcheck(name,total,parts, pages=None, note=None):
    t=dec(total); ps=list(map(dec,parts)); s=sum(ps,Decimal(0)); diff=t-s
    return {'name':name,'total_wanyuan':str(t),'parts_wanyuan':list(map(str,ps)),
            'formula': ' + '.join(map(str,ps)), 'sum_wanyuan':str(s),'difference_wanyuan':str(diff),
            'tolerance_wanyuan':'0.5','status':'confirmed_error' if abs(diff)>Decimal('.5') else 'within_tolerance',
            'pages':pages,'note':note}

def issue(label, rule, title, severity, page, snippet, expected, actual, reason, suggestion, related=None, difference=None, calculation=None, confidence=.99):
    e=evidence(label,page,snippet)
    result={'rule_id':rule,'title':title,'severity':severity,'document_type':'决算公开','year':2025,
            'organization':NAMES[label],'page':page,'bbox':e['bbox'],'table_or_section':None,
            'snippet':snippet,'expected':expected,'actual':actual,'difference':difference,'reason':reason,
            'suggestion':suggestion,'confidence':confidence,'evidence':[e]+(related or [])}
    if calculation: result['decimal_calculation']=calculation
    return result

