for label, obj in R.items():
    obj['freeze_metadata']['confirmed_issue_count']=len(obj['issues'])
    obj['freeze_metadata']['manual_review_count']=len(obj['manual_review'])
    obj['checks']['rate_count']=len(obj['checks']['rates'])
    obj['checks']['budget_comparison_count']=len(obj['checks']['budget_comparisons'])
    path=OUT/(label+'.json')
    path.write_text(json.dumps(obj,ensure_ascii=False,indent=2),encoding='utf-8')
    print(label, 'confirmed=',len(obj['issues']), 'manual=',len(obj['manual_review']), 'rates=',len(obj['checks']['rates']), 'budget_items=',len(obj['checks']['budget_comparisons']), 'sha256=',hashlib.sha256(path.read_bytes()).hexdigest())
